package com.fixflow.mall.api;

import com.fixflow.mall.domain.MallOrder;
import com.fixflow.mall.service.OrderService;
import com.fixflow.mall.service.UserService;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;

import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;

@ExtendWith(MockitoExtension.class)
class MallControllerTest {

    @Mock
    private UserService userService;

    @Mock
    private OrderService orderService;

    @InjectMocks
    private MallController mallController;

    private MallOrder testOrder;

    @BeforeEach
    void setUp() {
        testOrder = new MallOrder();
        testOrder.setId(1L);
        testOrder.setUserId(100L);
        testOrder.setItemId(200L);
    }

    @Test
    @DisplayName("正向测试：修复后的方法在正常输入下能正确工作")
    void getOrder_ValidOrderId_ShouldReturnOrder() {
        // Given
        Long orderId = 1L;
        when(orderService.findOrder(orderId)).thenReturn(testOrder);

        // When
        MallOrder result = mallController.getOrder(orderId);

        // Then
        assertNotNull(result);
        assertEquals(testOrder, result);
        verify(orderService, times(1)).findOrder(orderId);
    }

    @Test
    @DisplayName("边界测试：验证原来导致异常的输入现在不再抛出异常")
    @SuppressWarnings("ConstantConditions")
    void getOrder_WithPathVariableBinding_ShouldNotThrowException() {
        // Given - 模拟原来会导致MissingPathVariableException的场景
        Long orderId = 2L;
        MallOrder expectedOrder = new MallOrder();
        expectedOrder.setId(orderId);
        expectedOrder.setUserId(200L);
        expectedOrder.setItemId(300L);

        when(orderService.findOrder(orderId)).thenReturn(expectedOrder);

        // When & Then - 验证不再抛出MissingPathVariableException
        assertDoesNotThrow(() -> {
            MallOrder result = mallController.getOrder(orderId);
            assertNotNull(result);
            assertEquals(expectedOrder.getId(), result.getId());
        });

        verify(orderService, times(1)).findOrder(orderId);
    }

    @Test
    @DisplayName("空值测试：验证null值处理")
    void getOrder_NullOrderId_ShouldHandleGracefully() {
        // Given
        Long orderId = null;

        // When & Then - 验证不会抛出异常，或者正确处理null值
        // 注意：这里假设orderService.findOrder可以处理null，或者控制器有适当的错误处理
        try {
            mallController.getOrder(orderId);
            // 如果方法能处理null而不抛出异常，测试通过
        } catch (Exception e) {
            // 如果抛出异常，验证是预期的异常类型
            assertThrows(NullPointerException.class, () -> {
                mallController.getOrder(orderId);
            });
        }
    }

    @Test
    @DisplayName("正向测试：验证其他方法也能正常工作")
    void nickname_ValidUserId_ShouldReturnNickname() {
        // Given
        Long userId = 100L;
        String expectedNickname = "testUser";
        when(userService.getNickname(userId)).thenReturn(expectedNickname);

        // When
        String result = mallController.nickname(userId);

        // Then
        assertNotNull(result);
        assertEquals(expectedNickname, result);
        verify(userService, times(1)).getNickname(userId);
    }
}
